class Solution:
    def countVisitedNodes(self, edges):
        n = len(edges)
        ans = [0] * n
        for s in range(n):
            if ans[s]:
                continue
            path, seen = [], {}
            x = s
            while ans[x] == 0 and x not in seen:
                seen[x] = len(path)
                path.append(x)
                x = edges[x]
            if ans[x]:
                base = ans[x]
                for i in range(len(path) - 1, -1, -1):
                    ans[path[i]] = base + len(path) - i
            else:
                cyc = len(path) - seen[x]
                for i, node in enumerate(path):
                    ans[node] = cyc + max(0, seen[x] - i)
        return ans

