class Solution {
public:
    vector<int> countVisitedNodes(vector<int>& edges) {
        int n = edges.size();
        vector<int> ans(n, 0);
        for (int s = 0; s < n; s++) {
            if (ans[s]) continue;
            vector<int> path;
            unordered_map<int,int> seen;
            int x = s;
            while (!ans[x] && !seen.count(x)) {
                seen[x] = path.size();
                path.push_back(x);
                x = edges[x];
            }
            if (ans[x]) {
                int base = ans[x];
                for (int i = path.size() - 1; i >= 0; i--)
                    ans[path[i]] = base + (int)path.size() - i;
            } else {
                int cyc = path.size() - seen[x];
                for (int i = 0; i < (int)path.size(); i++)
                    ans[path[i]] = cyc + max(0, seen[x] - i);
            }
        }
        return ans;
    }
};

