class Solution {
    public int[] countVisitedNodes(int[] edges) {
        int n = edges.length;
        int[] ans = new int[n];
        for (int s = 0; s < n; s++) {
            if (ans[s] != 0) continue;
            List<Integer> path = new ArrayList<>();
            Map<Integer,Integer> seen = new HashMap<>();
            int x = s;
            while (ans[x] == 0 && !seen.containsKey(x)) {
                seen.put(x, path.size());
                path.add(x);
                x = edges[x];
            }
            if (ans[x] != 0) {
                int base = ans[x];
                for (int i = path.size() - 1; i >= 0; i--)
                    ans[path.get(i)] = base + path.size() - i;
            } else {
                int cyc = path.size() - seen.get(x);
                for (int i = 0; i < path.size(); i++)
                    ans[path.get(i)] = cyc + Math.max(0, seen.get(x) - i);
            }
        }
        return ans;
    }
}

