var countVisitedNodes = function(edges) {
    const n = edges.length, ans = new Array(n).fill(0);
    for (let s = 0; s < n; s++) {
        if (ans[s]) continue;
        const path = [], seen = new Map();
        let x = s;
        while (!ans[x] && !seen.has(x)) {
            seen.set(x, path.length);
            path.push(x);
            x = edges[x];
        }
        if (ans[x]) {
            const base = ans[x];
            for (let i = path.length - 1; i >= 0; i--)
                ans[path[i]] = base + path.length - i;
        } else {
            const cyc = path.length - seen.get(x);
            path.forEach((node, i) => {
                ans[node] = cyc + Math.max(0, seen.get(x) - i);
            });
        }
    }
    return ans;
};
